#!/bin/bash
# run_simulation_test.sh
#
# End-to-end simulation test for FusionANNS centroid recall evaluation.
# Tests whether SPTAG graph search achieves recall > 0.99 at nprobe=10000
# on 1.7M centroids with dim=256.
#
# Usage:
#   bash scripts/run_simulation_test.sh [--threads N] [--skip-datagen] [--skip-build-graph]

set -euo pipefail

export XMAKE_ROOT=y

# ─── Configuration ───────────────────────────────────────────────────
NLIST=1700000
DIM=256
NQ=10000
TOPK_GT=10000
TOTAL_VECTORS=110000000
M_SUB=64
THREADS=${THREADS:-48}
SKIP_DATAGEN=false
SKIP_BUILD_GRAPH=false

DATA_DIR="data/simulation"
INDEX_DIR="indices_simulation"

# Parse arguments
while [[ $# -gt 0 ]]; do
  case $1 in
    --threads) THREADS="$2"; shift 2 ;;
    --skip-datagen) SKIP_DATAGEN=true; shift ;;
    --skip-build-graph) SKIP_BUILD_GRAPH=true; shift ;;
    *) echo "Unknown option: $1"; exit 1 ;;
  esac
done

echo "=============================================="
echo " FusionANNS Simulation Performance Test"
echo "=============================================="
echo "  nlist           = $NLIST"
echo "  dim             = $DIM"
echo "  queries         = $NQ"
echo "  GT top-k        = $TOPK_GT"
echo "  total_vectors   = $TOTAL_VECTORS"
echo "  PQ sub-quant M  = $M_SUB"
echo "  threads         = $THREADS"
echo "  data_dir        = $DATA_DIR"
echo "  index_dir       = $INDEX_DIR"
echo "=============================================="
echo ""

# ─── Step 1: Generate simulation data ────────────────────────────────
if [ "$SKIP_DATAGEN" = false ]; then
  echo "========== Step 1: Generate simulation data =========="
  python3 scripts/gen_simulation_data.py \
    --nlist "$NLIST" \
    --dim "$DIM" \
    --nq "$NQ" \
    --topk "$TOPK_GT" \
    --output-dir "$DATA_DIR" \
    --seed 42 \
    --gt-chunk 20000
  echo ""
else
  echo "========== Step 1: SKIPPED (--skip-datagen) =========="
  echo ""
fi

# Verify data files exist
for f in centroids.fvecs queries.fvecs groundtruth_centroids.ivecs; do
  if [ ! -f "$DATA_DIR/$f" ]; then
    echo "ERROR: Missing $DATA_DIR/$f"
    exit 1
  fi
done
echo "Data files verified."
echo ""

# ─── Step 2: Build SPTAG centroid graph ──────────────────────────────
if [ "$SKIP_BUILD_GRAPH" = false ]; then
  echo "========== Step 2: Build SPTAG centroid graph =========="
  mkdir -p "$INDEX_DIR"

  # Build the tool if needed
  if [ ! -f bin/build_centroid_graph_standalone ]; then
    echo "  Building build_centroid_graph_standalone..."
    xmake build build_centroid_graph_standalone
  fi

  ./bin/build_centroid_graph_standalone \
    --centroids "$DATA_DIR/centroids.fvecs" \
    --output "$INDEX_DIR/proximity_graph_index" \
    --threads "$THREADS"
  echo ""
else
  echo "========== Step 2: SKIPPED (--skip-build-graph) =========="
  echo ""
fi

# Verify graph exists
if [ ! -d "$INDEX_DIR/proximity_graph_index" ]; then
  echo "ERROR: Missing $INDEX_DIR/proximity_graph_index"
  exit 1
fi
echo "SPTAG graph verified."
echo ""

# ─── Step 3: Evaluate centroid recall ────────────────────────────────
echo "========== Step 3: Evaluate centroid recall =========="

# Build the tool if needed
if [ ! -f bin/eval_centroid_recall ]; then
  echo "  Building eval_centroid_recall..."
  xmake build eval_centroid_recall
fi

./bin/eval_centroid_recall \
  --graph "$INDEX_DIR/proximity_graph_index" \
  --queries "$DATA_DIR/queries.fvecs" \
  --groundtruth "$DATA_DIR/groundtruth_centroids.ivecs" \
  --nprobe "1000,2000,5000,8000,10000,12000,15000,20000" \
  --recall_k "$TOPK_GT" \
  --threads "$THREADS"
echo ""

# ─── Step 4: Generate fake index for end-to-end latency test ────────
echo "========== Step 4: Generate fake index artifacts =========="

python3 scripts/gen_fake_index.py \
  --nlist "$NLIST" \
  --total-vectors "$TOTAL_VECTORS" \
  --dim "$DIM" \
  --m-sub "$M_SUB" \
  --output-dir "$INDEX_DIR"
echo ""

# Note: pq_codec needs to be generated by C++ tool (faiss::write_ProductQuantizer)
# For now, Steps 1-3 provide the centroid recall evaluation.
# Step 4 artifacts enable future query_server testing.

echo "========== Step 5: Latency estimation =========="
echo ""
echo "Latency model:"
echo "  T_total = T_graph(nprobe=10000 on 1.7M centroids)   [from Step 3]"
echo "          + T_pq(650K candidates, M=64)                [from Step 4 query_server]"
echo "          + T_rerank_est"
echo ""
echo "  T_rerank_est = rerank_size × (page_size / SSD_bandwidth + L2_compute)"
echo "               ≈ rerank_size × (4KB / 3.5GB/s + 256dim×2flop/10GFLOPS)"
echo ""
echo "To run full end-to-end test with query_server (after generating pq_codec):"
echo "  ./bin/query_server \\"
echo "    --query $DATA_DIR/queries.fvecs \\"
echo "    --groundtruth $DATA_DIR/groundtruth_centroids.ivecs \\"
echo "    --index-path $INDEX_DIR \\"
echo "    --nprobe 10000 --topk 100 \\"
echo "    --rerank_size 1 --rerank_delta 99999 \\"
echo "    --threads $THREADS --warmup 100"
echo ""
echo "=============================================="
echo " Simulation test complete!"
echo "=============================================="
